mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM wallets
    WHERE id = #{walletId}
        AND child_id = #{childId}
        AND status = 'ACTIVE'
)

mapper.update:
UPDATE wallets
SET balance = balance + #{amount}
WHERE id = #{walletId}
    AND status = 'ACTIVE'

UPDATE wallets
SET balance = balance - #{amount}
WHERE id = #{walletId}
    AND status = 'ACTIVE'
    AND balance >= #{amount}
